def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_nth_prime(n):
    count = 0
    num = 1
    primes = []
    while count < n:
        num += 1
        if is_prime(num):
            count += 1
            primes.append(num)
    return primes[-1]

N_target = 50
p_50 = find_nth_prime(N_target)
print(f"The {N_target}th prime number is: {p_50}")

